define({"topics":[{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_47.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e188227","topics":[]},{"title":"Replacing the Exciter","href":"t_ReplacingtheExciter.html","attributes":{"data-id":"id_2001530"},"menu":{"hasChildren":false},"tocID":"id_2001530-d46e188331","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_49.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e188432","topics":[]},{"title":"Calibrating RF Amplifier and UPM<span class=\"ph\"> or RF Amp and Power Monitor (RAP) Tool<\/span>","shortdesc":"<p class=\"shortdesc\">Calibrate the maximum power for the RF amplifier. Also, calibrate and check the Universal Power Monitor (UPM)<span class=\"ph\"> or RF Amp and Power Monitor (RAP) Tool<\/span> for each channel.<\/p>","href":"t_CalibratingRFAmplifierAndUPM_3.html","attributes":{"data-id":"id_2002056"},"menu":{"hasChildren":true},"tocID":"id_2002056-d46e188537","next":"id_2002056-d46e188537"},{"title":"Calibrating for quadrature","href":"t_CalibratingForQuadrature_4.html","attributes":{"data-id":"id_2001634"},"menu":{"hasChildren":false},"tocID":"id_2001634-d46e192158","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_75.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e192259","topics":[]}]});